sysauto_script.script:
// Helper function for logging to app log table
function logRenewalNotification(logLevel, message) {
    var gr = new GlideRecord('x_1784056_sixscape_log');
    gr.initialize();
    gr.log_level = logLevel;
    gr.script = "Renewal Notification";
    gr.application = "Sixscape IDC";
    gr.message = message;
    gr.insert();

    // Optionally, also log to sys logs
    if (logLevel === "Info") gs.info(message);
    else if (logLevel === "Warning") gs.warn(message);
    else gs.error(message);
}

try {
    var profileGR = new GlideRecord('x_1784056_sixscape_profile');
    profileGR.addNotNullQuery('renewal_threshold');
    profileGR.addNotNullQuery('assignment_group');
    profileGR.query();

    while (profileGR.next()) {
        var threshold = parseInt(profileGR.renewal_threshold, 10);
        var groupSysId = profileGR.assignment_group.toString();

        var thresholdDate = new GlideDateTime();
        thresholdDate.addDaysUTC(threshold); // Adds threshold days to today

        var msg = "Checking devices for profile '" + profileGR.profile_name + "' (" + profileGR.getUniqueValue() + 
            "), renewal threshold: " + threshold + " days; thresholdDate: " + thresholdDate.getDisplayValue();
        logRenewalNotification("Info", msg);

        // Get all devices under this profile with expiryDate within threshold
        var nowDate = new GlideDateTime();
        var deviceGR = new GlideRecord('x_1784056_sixscape_device');
        deviceGR.addQuery('profile', profileGR.getUniqueValue());
        deviceGR.addQuery('expiry_date', '<=', thresholdDate);
        deviceGR.addQuery('expiry_date', '>=', nowDate);
        deviceGR.query();

        var foundDevices = 0;
        while (deviceGR.next()) {
            gs.eventQueue(
                'x_1784056_sixscape.renewal_notification',
                deviceGR,
                groupSysId,
                ''
            );
            var deviceDisplay = deviceGR.getDisplayValue() || deviceGR.sys_id.toString();
            var expiryDisplay = deviceGR.expiry_date ? deviceGR.expiry_date.getDisplayValue() : 'N/A';
            logRenewalNotification(
                "Info",
                "Renewal notification event fired for device: " + deviceDisplay + 
                " (expiry: " + expiryDisplay + ", group: " + groupSysId + ")"
            );
            foundDevices++;
        }

        if (foundDevices === 0) {
            logRenewalNotification(
                "Info",
                "No devices found approaching expiry (within threshold) for profile: " +
                profileGR.profile_name + " (" + profileGR.getUniqueValue() + ")"
            );
        }
    }
    logRenewalNotification("Info", "Renewal Notification script execution completed.");
} catch (ex) {
    logRenewalNotification("Error", "Error in Renewal Notification script: " + ex.message);
}
